import * as NodeFS from "node:fs";
import * as NodeOS from "node:os";
import * as NodePath from "node:path";

/** A fake %LOCALAPPDATA% holding one extracted Construct repo whose markers say the VM
 *  was provisioned with an OLDER Construct than the one installed on this PC. */
function makeConstructInstall(): string {
  const localAppData = NodeFS.mkdtempSync(NodePath.join(NodeOS.tmpdir(), "t3-construct-updates-"));
  const scriptsDir = NodePath.join(
    localAppData,
    "The-Construct",
    "permissionBRICK-The-Construct-main",
    "The-Construct-main",
  );
  NodeFS.mkdirSync(scriptsDir, { recursive: true });
  NodeFS.writeFileSync(NodePath.join(scriptsDir, "Auto-Install.ps1"), "# marker\n");
  NodeFS.writeFileSync(NodePath.join(scriptsDir, "Update-T3Code.ps1"), "# reprovision\n");
  NodeFS.writeFileSync(
    NodePath.join(scriptsDir, ".construct-settings.json"),
    "\uFEFF" +
      JSON.stringify({
        installedCommit: "dc44958114c7c43145c8f7830f6185235a1d752b",
        provisionedCommit: "b262652aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
      }),
  );
  return localAppData;
}

describe("DesktopUpdates (Construct builds)", () => {
  it.effect("seeds the Construct facts from the local markers at configure time", () =>
    Effect.gen(function* () {
      const localAppData = makeConstructInstall();
      const harness = makeHarness({
        appVersion: "0.0.38-construct.bb8cb346",
        env: { LOCALAPPDATA: localAppData },
      });
      yield* Effect.gen(function* () {
        const updates = yield* DesktopUpdates.DesktopUpdates;
        yield* Effect.scoped(updates.configure);
        const state = yield* updates.getState;
        assert.isTrue(state.enabled);
        assert.equal(state.status, "available");
        assert.equal(state.channel, "latest");
        assert.isDefined(state.construct);
        assert.equal(state.construct?.installedCommit, "dc44958114c7c43145c8f7830f6185235a1d752b");
        assert.isTrue(state.construct?.provisionStale);
        assert.equal(state.construct?.action, "reprovision");
        assert.equal(state.construct?.vmName, "agent-vm");
        // electron-updater never ran an update check.
        assert.equal(harness.checkCount(), 0);
        // The channel preference cannot be changed on a Construct build.
        const afterChannel = yield* updates.setChannel("nightly");
        assert.equal(afterChannel.channel, "latest");
      }).pipe(Effect.provide(harness.layer));
      NodeFS.rmSync(localAppData, { recursive: true, force: true });
    }),
  );

  it.effect("keeps the facts but launches nothing while auto-updates are disabled", () =>
    Effect.gen(function* () {
      const localAppData = makeConstructInstall();
      const harness = makeHarness({
        appVersion: "0.0.38-construct.bb8cb346",
        env: { LOCALAPPDATA: localAppData, T3CODE_DISABLE_AUTO_UPDATE: "true" },
      });
      yield* Effect.gen(function* () {
        const updates = yield* DesktopUpdates.DesktopUpdates;
        yield* Effect.scoped(updates.configure);
        const state = yield* updates.getState;
        assert.isFalse(state.enabled);
        assert.equal(state.status, "disabled");
        assert.isTrue(state.construct?.provisionStale);
        assert.equal(state.construct?.action, "reprovision");
        assert.isTrue(Option.isSome(yield* updates.disabledReason));
        const check = yield* updates.check("web-ui");
        assert.isFalse(check.checked);
        const download = yield* updates.download;
        assert.isFalse(download.completed);
        assert.equal(download.state.status, "disabled");
        assert.include(download.state.message ?? "", "T3CODE_DISABLE_AUTO_UPDATE");
        assert.isNull(download.state.construct?.runningAction ?? null);
      }).pipe(Effect.provide(harness.layer));
      NodeFS.rmSync(localAppData, { recursive: true, force: true });
    }),
  );
});

import type {
  ConstructPairingLinkResult,
  ConstructT3LinkInfo,
  ConstructUpdateAction,
  ConstructUpdateInfo,
} from "@t3tools/contracts";

// Construct-built Desktop apps (see ConstructUpdates.ts) replace electron-updater with
// checks against Construct's GitHub ref + the T3 npm channel. GitHub allows 60
// unauthenticated requests/hour per IP and the VS Code control panel polls too, so
// the full check runs rarely; while a launched script runs only the local markers
// are re-read, and the script's exit triggers the next full check.
const CONSTRUCT_POLL_INTERVAL = "10 minutes";
const CONSTRUCT_RUNNING_REFRESH_INTERVAL = "15 seconds";
const CONSTRUCT_DISABLED_BY_ENV_REASON =
  "Construct-managed updates are disabled by the T3CODE_DISABLE_AUTO_UPDATE setting.";

// ── Construct-managed updates ──────────────────────────────────────────────
const constructManaged = ConstructUpdates.isConstructManagedBuild(environment.appVersion);
const constructDisabledReason = config.disableAutoUpdate
  ? Option.some(CONSTRUCT_DISABLED_BY_ENV_REASON)
  : Option.none<string>();
const constructEnabled = constructManaged && Option.isNone(constructDisabledReason);
const constructLocalAppData = yield* Config.string("LOCALAPPDATA").pipe(
  Config.option,
  Effect.orElseSucceed(() => Option.none<string>()),
  Effect.map(Option.getOrUndefined),
);
// The T3 channel of a Construct build is fixed by the VM's T3CODE_CHANNEL that built
// it, so the state reports the channel derived from the build version; the desktop
// updateChannel preference is not consulted (and setChannel is a no-op).
const constructChannel = ConstructUpdates.resolveConstructT3Channel(
  ConstructUpdates.constructT3BaseVersion(environment.appVersion),
);
const constructInfoRef = yield* Ref.make<ConstructUpdateInfo | null>(null);
const constructRunningRef = yield* Ref.make<ConstructUpdateAction | null>(null);
// One refresh or launch at a time: a poll that read the markers before a launch must
// not publish its stale snapshot over the running state, and the script-exit refresh
// must not interleave with a scheduled one.
const constructMutex = yield* Semaphore.make(1);
const constructContext = yield* Effect.context<never>();
const runConstructEffect = (effect: Effect.Effect<void>) => {
  void Effect.runPromiseWith(constructContext)(effect);
};

/** Re-read the Construct markers on this PC and (in "full" mode) ask GitHub + npm,
 *  then fold the result into the broadcast state. Never fails. */
const refreshConstruct = Effect.fn("desktop.updates.construct.refresh")(function* (
  reason: string,
  mode: "full" | "local",
) {
  yield* Effect.annotateCurrentSpan({ reason, mode });
  return yield* constructMutex.withPermits(1)(refreshConstructLocked(reason, mode));
});

const refreshConstructLocked = Effect.fn("desktop.updates.construct.refreshLocked")(function* (
  reason: string,
  mode: "full" | "local",
) {
  const previous = yield* Ref.get(constructInfoRef);
  const runningAction = yield* Ref.get(constructRunningRef);
  const checkedAt = yield* currentIsoTimestamp;
  if (mode === "full") {
    yield* updateState((current) => reduceDesktopUpdateStateOnCheckStart(current, checkedAt));
  }
  const info = yield* Effect.promise(() =>
    ConstructUpdates.checkConstructUpdates({
      appVersion: environment.appVersion,
      localAppData: constructLocalAppData,
      fs: ConstructUpdates.nodeConstructFileSystem,
      ...(mode === "full" ? { fetchJson: ConstructUpdates.fetchConstructJson } : {}),
      previous,
      runningAction,
      now: () => checkedAt,
    }),
  );
  // A script finished (or was launched) while the check was in flight: its own
  // handler publishes the authoritative state; this snapshot is stale.
  if ((yield* Ref.get(constructRunningRef)) !== runningAction) {
    yield* logUpdaterInfo("construct update check superseded", { reason, mode });
    return previous ?? info;
  }
  yield* Ref.set(constructInfoRef, info);
  // With T3CODE_DISABLE_AUTO_UPDATE the Construct facts are still published (the
  // Providers entry and the read-only update track need them) but the control stays
  // disabled and nothing is offered.
  yield* updateState((current) => ({
    ...ConstructUpdates.applyConstructInfoToState(current, info),
    channel: constructChannel,
    ...(constructEnabled ? {} : { enabled: false, status: "disabled" as const }),
  }));
  yield* logUpdaterInfo("construct update check", {
    reason,
    mode,
    action: info.action,
    runningAction: info.runningAction,
    installedCommit: info.installedCommit,
    provisionedCommit: info.provisionedCommit,
    behind: info.behind,
    t3LatestVersion: info.t3LatestVersion,
    error: info.error,
  });
  return info;
});

const handleConstructExit = Effect.fn("desktop.updates.construct.exit")(function* (
  action: ConstructUpdateAction,
  result: { readonly code: number | null; readonly error: string | null },
) {
  yield* Ref.set(constructRunningRef, null);
  yield* finishUpdateAction("download");
  yield* logUpdaterInfo("construct script finished", {
    action,
    code: result.code,
    error: result.error,
  });
  const info = yield* refreshConstruct("script-exit", "full");
  if (result.error === null && (result.code === null || result.code === 0)) return;
  // Update-T3Code.ps1 exits 1 when provisioning failed and 3 when it finished with
  // optional errors (the provisioner's own codes); Update-Construct.ps1 exits 1.
  const message =
    result.error ??
    (result.code === 3
      ? `${ConstructUpdates.constructScriptFileName(action)} finished with optional errors (exit code 3). See its console output for details.`
      : `${ConstructUpdates.constructScriptFileName(action)} exited with code ${result.code}. See its console output for details.`);
  const failed: ConstructUpdateInfo = {
    ...info,
    error: info.error === null ? message : `${message} ${info.error}`,
  };
  yield* Ref.set(constructInfoRef, failed);
  yield* updateState((current) => ({
    ...ConstructUpdates.applyConstructInfoToState(current, failed),
    message,
    errorContext: "download",
    canRetry: true,
  }));
  yield* logUpdaterError(message, { action, code: result.code });
});

/** Re-read the local markers every few seconds while a script runs, so the state
 *  follows Update-Construct.ps1 (installedCommit moves) / the provisioner
 *  (provisionedCommit moves) without waiting for the console to close. */
const watchConstructRun = Effect.gen(function* () {
  while (true) {
    yield* Effect.sleep(CONSTRUCT_RUNNING_REFRESH_INTERVAL);
    if ((yield* Ref.get(constructRunningRef)) === null) return;
    yield* refreshConstruct("script-running", "local");
  }
}).pipe(
  Effect.catchCause((cause) =>
    Cause.hasInterruptsOnly(cause)
      ? Effect.void
      : logUpdaterWarning("construct run watcher failed", { cause: Cause.pretty(cause) }),
  ),
  Effect.withSpan("desktop.updates.construct.watchRun"),
);

/** The update control was clicked: run the script the last check offered. */
/** The update control was clicked, or ONE Providers row's Reprovision (B14, plan
 *  §4.12): `instanceName` names the VM that row is about. Without it this is the
 *  host-wide control and the action is whatever the last check offered. */
const launchConstruct = Effect.fn("desktop.updates.construct.launch")(function* (
  instanceName?: string,
) {
  return yield* constructMutex.withPermits(1)(launchConstructLocked(instanceName));
});

const launchConstructLocked = Effect.fn("desktop.updates.construct.launchLocked")(function* (
  instanceName?: string,
) {
  const info = yield* Ref.get(constructInfoRef);
  // A NAMED launch is always a reprovision of that instance: a row can be stale (or
  // simply chosen) while the host-wide control has nothing to offer, so `info.action`
  // must not gate it. A launch already running still blocks both.
  const named = instanceName !== undefined && instanceName !== "";
  if (info === null || info.runningAction !== null) {
    return { accepted: false, completed: false };
  }
  if (!named && info.action === null) {
    return { accepted: false, completed: false };
  }
  if (!constructEnabled) {
    // The renderer gates its controls on `enabled`; a call that still gets here
    // (an older web client) is answered with the reason, never with a launch.
    yield* updateState((current) => ({
      ...current,
      message: CONSTRUCT_DISABLED_BY_ENV_REASON,
      errorContext: "download",
    }));
    return { accepted: true, completed: false };
  }
  if (!(yield* tryStartUpdateAction("download"))) {
    return { accepted: false, completed: false };
  }
  const action: ConstructUpdateAction = named ? "reprovision" : info.action!;
  // Re-read the registry now: the target VM is what Update-T3Code.ps1 is told to
  // reprovision, and it must match what the check displayed a moment ago.
  const planned = named
    ? ConstructUpdates.planConstructInstanceReprovision(
        instanceName!,
        ConstructUpdates.readConstructInstancesFromRegistry(
          constructLocalAppData,
          ConstructUpdates.nodeConstructFileSystem,
        ),
        info,
        environment.platform,
        ConstructUpdates.nodeConstructFileSystem,
      )
    : ConstructUpdates.planConstructLaunch(
        action,
        info,
        ConstructUpdates.readConstructVmTargetFromRegistry(
          constructLocalAppData,
          ConstructUpdates.nodeConstructFileSystem,
        ),
        environment.platform,
        ConstructUpdates.nodeConstructFileSystem,
      );
  if (!planned.ok) {
    yield* finishUpdateAction("download");
    const failed: ConstructUpdateInfo = { ...info, error: planned.error };
    yield* Ref.set(constructInfoRef, failed);
    yield* updateState((current) => ({
      ...ConstructUpdates.applyConstructInfoToState(current, failed),
      message: planned.error,
      errorContext: "download",
      canRetry: true,
    }));
    yield* logUpdaterError(planned.error, { action });
    return { accepted: true, completed: false };
  }
  yield* Ref.set(constructRunningRef, action);
  const running: ConstructUpdateInfo = { ...info, runningAction: action, error: null };
  yield* Ref.set(constructInfoRef, running);
  yield* updateState((current) => ConstructUpdates.applyConstructInfoToState(current, running));
  const handle = ConstructUpdates.spawnConstructLaunch(planned.plan, (result) => {
    runConstructEffect(
      handleConstructExit(action, result).pipe(
        Effect.catchCause((cause) =>
          Cause.hasInterruptsOnly(cause)
            ? Effect.void
            : logUpdaterError("construct script exit handling failed", {
                cause: Cause.pretty(cause),
              }),
        ),
      ),
    );
  });
  if (handle !== null) {
    yield* logUpdaterInfo("launched construct script", {
      action,
      scriptPath: planned.plan.scriptPath,
      target: named ? instanceName! : "default",
      pid: handle.pid ?? null,
    });
    runConstructEffect(watchConstructRun);
  }
  return { accepted: true, completed: false };
});

const startConstructPollers: Effect.Effect<void, never, Scope.Scope> = Effect.gen(function* () {
  const poll = (reason: string) =>
    Ref.get(constructRunningRef).pipe(
      Effect.flatMap((running) => refreshConstruct(reason, running === null ? "full" : "local")),
      Effect.asVoid,
    );
  yield* Effect.sleep(AUTO_UPDATE_STARTUP_DELAY).pipe(
    Effect.andThen(poll("startup")),
    Effect.catchCause((cause) => {
      if (Cause.hasInterruptsOnly(cause)) {
        return Effect.void;
      }
      const error = new DesktopUpdatePollerError({ poller: "startup", cause });
      return logUpdaterError(error.message, { errorTag: error._tag, poller: error.poller });
    }),
    Effect.forkScoped,
  );
  yield* Effect.sleep(CONSTRUCT_POLL_INTERVAL).pipe(
    Effect.andThen(poll("poll")),
    Effect.forever,
    Effect.catchCause((cause) => {
      if (Cause.hasInterruptsOnly(cause)) {
        return Effect.void;
      }
      const error = new DesktopUpdatePollerError({ poller: "poll", cause });
      return logUpdaterError(error.message, { errorTag: error._tag, poller: error.poller });
    }),
    Effect.forkScoped,
  );
}).pipe(Effect.withSpan("desktop.updates.construct.startPollers"));

if (constructManaged) {
  yield* setState(createBaseUpdateState(constructChannel, constructEnabled, environment));
  // Seed the Construct facts from the local markers/registry right away (no
  // network): the renderer's first read must already know this is a Construct
  // build, whether or not the remote checks are enabled.
  yield* refreshConstruct("configure", "local");
  if (!constructEnabled) {
    return;
  }
  yield* logUpdaterInfo("construct-managed updates enabled", {
    appVersion: environment.appVersion,
  });
  yield* startConstructPollers;
  return;
}

if (constructManaged) {
  // The channel is decided by the VM's T3CODE_CHANNEL (Construct control panel);
  // the About section hides the selector for Construct builds.
  return state;
}

if (constructManaged) {
  if (!constructEnabled) {
    return { checked: false, state: yield* Ref.get(updateStateRef) };
  }
  if ((yield* Ref.get(constructRunningRef)) !== null) {
    // A launched script is running: its exit triggers the full check.
    yield* refreshConstruct(reason, "local");
    return { checked: true, state: yield* Ref.get(updateStateRef) };
  }
  if (yield* tryStartUpdateAction("check")) {
    yield* refreshConstruct(reason, "full").pipe(
      Effect.ensuring(finishUpdateAction("check")),
    );
  }
  return { checked: true, state: yield* Ref.get(updateStateRef) };
}

