/**
 * Resolves `T3CODE_PUBLIC_BASE_URL` for a served runtime, warning instead of
 * silently falling back when it is set to something unusable.
 */
const resolvePublicBaseUrlForServing = Effect.fn("server.startup.publicBaseUrl")(function* (
  mode: ServerConfig.RuntimeMode,
) {
  if (mode === "desktop") return undefined;
  const setting = readPublicBaseUrl();
  if (setting.kind === "invalid") {
    yield* Effect.logWarning(
      "Ignoring T3CODE_PUBLIC_BASE_URL: it is not an http(s) URL. Using the bind address instead.",
    ).pipe(Effect.annotateLogs({ publicBaseUrl: setting.raw }));
    return undefined;
  }
  return setting.kind === "ok" ? setting.origin : undefined;
});

