import { MicIcon, SquareIcon } from "lucide-react";
import { useServerConfigs } from "../../state/entities";
import {
  sendVoiceAudio as sendVoiceAudioCommand,
  startVoiceInput as startVoiceInputCommand,
  stopVoiceInput as stopVoiceInputCommand,
} from "../../state/voiceInput";
import {
  canCaptureClientAudio,
  isSecureContext,
  resolveVoiceInputSource,
  startClientAudioCapture,
  type ClientAudioCapture,
} from "../../voice/clientAudioCapture";
import {
  createVoiceAudioSender,
  MAX_PENDING_VOICE_CHUNKS,
  type VoiceAudioSender,
} from "../../voice/voiceAudioSender";
import { describeVoiceInputFailure } from "../../voice/voiceInputFailure";
import { useClientSettings } from "../../hooks/useSettings";

/**
 * A live voice session's insertion window plus, for client-captured audio, the
 * microphone and the sender pushing it to the server.
 */
type VoiceInsertionState = {
  sessionId: string;
  targetKey: string;
  prefix: string;
  suffix: string;
  rendered: string;
  lastSetInput: string;
  source: "client" | "host";
  capture: ClientAudioCapture | null;
  sender: VoiceAudioSender | null;
  /** Audio captured before the server said `listening`; flushed once it does. */
  buffered: Array<Uint8Array>;
  stopRequested: boolean;
};

/** Idempotent, so every path that drops a session can call it. */
function releaseVoiceCapture(insertion: VoiceInsertionState | null): void {
  if (!insertion) return;
  insertion.capture?.stop();
  insertion.capture = null;
  insertion.sender?.stop();
  insertion.sender = null;
  insertion.buffered.length = 0;
}

const serverConfigs = useServerConfigs();
const supportsVoiceInput =
  serverConfigs.get(environmentId)?.environment.capabilities.voiceInput === true;
const supportsClientVoiceAudio =
  serverConfigs.get(environmentId)?.environment.capabilities.voiceInputClientAudio === true;
const voiceInputSourcePreference = useClientSettings((settings) => settings.voiceInputSource);
const voiceInputSource = resolveVoiceInputSource({
  preference: voiceInputSourcePreference,
  canCaptureHere: canCaptureClientAudio(),
  serverAcceptsClientAudio: supportsClientVoiceAudio,
  secureContext: isSecureContext(),
});
const voiceSourceHint =
  voiceInputSource.source === "client"
    ? "records with this device's microphone"
    : voiceInputSource.source === "host"
      ? "records through the Construct host bridge"
      : voiceInputSource.reason;
const runStartVoiceInput = useAtomCommand(startVoiceInputCommand, { reportFailure: false });
const runStopVoiceInput = useAtomCommand(stopVoiceInputCommand, { reportFailure: false });
const runSendVoiceAudio = useAtomCommand(sendVoiceAudioCommand, { reportFailure: false });

// The question answer is a separate draft from the regular chat prompt.
const voiceInputValue = activePendingProgress?.customAnswer ?? prompt;
const voiceTargetKey = JSON.stringify([
  composerTargetKey(composerDraftTarget),
  activePendingUserInput?.requestId ?? null,
  activePendingProgress?.activeQuestion?.id ?? null,
]);
const voiceTargetRef = useRef(voiceTargetKey);
voiceTargetRef.current = voiceTargetKey;

const stopVoiceRecording = useCallback(() => {
  setVoiceLevel(0);
  const insertion = voiceInsertionRef.current;
  if (!insertion) return;
  insertion.stopRequested = true;
  releaseVoiceCapture(insertion);
  void runStopVoiceInput({ environmentId, sessionId: insertion.sessionId });
}, [environmentId, runStopVoiceInput]);

const startVoiceRecording = useCallback(() => {
  if (!supportsVoiceInput || voiceInsertionRef.current || environmentUnavailable !== null) return;
  if (voiceInputSource.source === null) {
    toastManager.add({
      type: "error",
      title: "Voice input unavailable",
      description: voiceInputSource.reason,
    });
    return;
  }
  const source = voiceInputSource.source;
  const snapshot = readComposerSnapshot();
  const sessionId = randomUUID();
  const insertion: VoiceInsertionState = {
    sessionId,
    targetKey: voiceTargetRef.current,
    prefix: snapshot.value.slice(0, snapshot.expandedCursor),
    suffix: snapshot.value.slice(snapshot.expandedCursor),
    rendered: "",
    lastSetInput: snapshot.value,
    source,
    capture: null,
    sender: null,
    buffered: [],
    stopRequested: false,
  };
  voiceInsertionRef.current = insertion;
  setIsVoiceRecording(true);
  setVoiceLevel(0);

  if (source === "client") {
    // The permission prompt can take seconds, so the microphone comes up in
    // parallel with the session rather than after it.
    insertion.capture = startClientAudioCapture({
      onChunk: (chunk) => {
        if (voiceInsertionRef.current !== insertion) return;
        if (insertion.sender) {
          insertion.sender.push(chunk);
          return;
        }
        // Not listening yet: keep the newest ~0.8 s so the first word
        // survives the round trip instead of being dropped.
        insertion.buffered.push(chunk);
        if (insertion.buffered.length > MAX_PENDING_VOICE_CHUNKS) insertion.buffered.shift();
      },
      onLevel: (level) => {
        if (voiceInsertionRef.current !== insertion) return;
        setVoiceLevel(level);
      },
      onError: (message) => {
        if (voiceInsertionRef.current !== insertion) return;
        stopVoiceRecording();
        toastManager.add({
          type: "error",
          title: "Voice input stopped",
          description: message,
        });
      },
    });
  }

  void runStartVoiceInput({
    environmentId,
    sessionId,
    source,
    onEvent: (event) => {
      const active = voiceInsertionRef.current;
      if (!active || active.sessionId !== sessionId) return;
      if (event.type === "level") {
        setVoiceLevel(event.value);
        return;
      }
      if (event.type === "listening") {
        if (active.source !== "client") return;
        if (active.stopRequested) {
          // The user stopped before the server was ready to record.
          void runStopVoiceInput({ environmentId, sessionId });
          return;
        }
        const sender = createVoiceAudioSender({
          send: (chunk) => runSendVoiceAudio({ environmentId, sessionId, chunk }),
        });
        active.sender = sender;
        for (const chunk of active.buffered) sender.push(chunk);
        active.buffered.length = 0;
        return;
      }
      if (event.type === "stopped") {
        releaseVoiceCapture(active);
        voiceInsertionRef.current = null;
        setIsVoiceRecording(false);
        setVoiceLevel(0);
        return;
      }
      if (event.type !== "transcript") return;
      // Claude's composer stops voice mode if the user edits while a partial
      // transcript is live. That full-value guard prevents a later interim from
      // overwriting either the original prompt or the user's new edit.
      if (voiceTargetRef.current !== active.targetKey || readComposerSnapshot().value !== active.lastSetInput) {
        stopVoiceRecording();
        releaseVoiceCapture(active);
        voiceInsertionRef.current = null;
        setIsVoiceRecording(false);
        return;
      }
      // The editor snapshot is authoritative even before the pending-answer
      // effect has synchronized the shared prompt ref after a React update.
      promptRef.current = active.lastSetInput;
      const transcript = event.text.trim();
      const leading = transcript && active.prefix && !/\s$/u.test(active.prefix) ? " " : "";
      const trailing = transcript && active.suffix && !/^\s/u.test(active.suffix) ? " " : "";
      const rendered = transcript ? `${leading}${transcript}${trailing}` : "";
      const nextInput = `${active.prefix}${rendered}${active.suffix}`;
      const applied = applyPromptReplacement(
        active.prefix.length,
        active.prefix.length + active.rendered.length,
        rendered,
        { expectedText: active.rendered, focusEditorAfterReplace: false },
      );
      if (!applied) {
        stopVoiceRecording();
        releaseVoiceCapture(active);
        voiceInsertionRef.current = null;
        setIsVoiceRecording(false);
        return;
      }
      active.rendered = rendered;
      active.lastSetInput = nextInput;
      const expandedCursor = active.prefix.length + leading.length + transcript.length;
      const cursor = collapseExpandedComposerCursor(nextInput, expandedCursor);
      window.requestAnimationFrame(() => {
        if (voiceTargetRef.current === active.targetKey) composerEditorRef.current?.focusAt(cursor);
      });
    },
  }).then((result) => {
    releaseVoiceCapture(insertion);
    const active = voiceInsertionRef.current;
    if (active?.sessionId === sessionId) {
      voiceInsertionRef.current = null;
      setIsVoiceRecording(false);
      setVoiceLevel(0);
    }
    if (AsyncResult.isFailure(result)) {
      toastManager.add({
        type: "error",
        title: "Voice input stopped",
        // The server names its own failures (no client audio, host bridge
        // down, a transcription error); only unexplained ones fall back.
        description: describeVoiceInputFailure(result.cause, source),
      });
    }
  });
}, [
  applyPromptReplacement,
  environmentId,
  environmentUnavailable,
  promptRef,
  readComposerSnapshot,
  runSendVoiceAudio,
  runStartVoiceInput,
  runStopVoiceInput,
  stopVoiceRecording,
  supportsVoiceInput,
