  handler: Effect.fn("desktop.ipc.updates.constructRecordT3Link")(function* (input) {
    const updates = yield* DesktopUpdates.DesktopUpdates;
    if (updates.recordConstructInstanceT3Link === undefined) return false;
    return yield* updates.recordConstructInstanceT3Link(input.name, input.link);
  }),
});

/** Construct-managed builds: mint a T3 pairing link for ONE named instance (auto-link,
 *  plan section 4.12). Optional for the same reason as reprovisionConstructInstance. */
readonly linkConstructInstance?: (name: string) => Effect.Effect<ConstructPairingLinkResult>;
/** ...and record what the renderer did with it. True when the marker was written. */
readonly recordConstructInstanceT3Link?: (
  name: string,
  link: ConstructT3LinkInfo,
) => Effect.Effect<boolean>;

linkConstructInstance: Effect.fn("desktop.updates.constructLinkInstance")(function* (
  name: string,
) {
  if (!constructManaged) {
    return { ok: false as const, error: "Not a Construct-built Desktop app." };
  }
  const info = yield* Ref.get(constructInfoRef);
  const planned = ConstructUpdates.planConstructPairingLink(
    name,
    info,
    environment.platform,
    ConstructUpdates.nodeConstructFileSystem,
  );
  if (!planned.ok) return { ok: false as const, error: planned.error };
  yield* logUpdaterInfo("minting a T3 pairing link", { instance: name });
  const result = yield* Effect.promise(() =>
    ConstructUpdates.runConstructPairingLink(planned.plan),
  );
  if (!result.ok) {
    yield* logUpdaterWarning("T3 pairing link failed", { instance: name, error: result.error });
  }
  return result;
}),
recordConstructInstanceT3Link: Effect.fn("desktop.updates.constructRecordT3Link")(
  function* (name: string, link: ConstructT3LinkInfo) {
    if (!constructManaged) return false;
    const info = yield* Ref.get(constructInfoRef);
    const written = ConstructUpdates.recordConstructInstanceT3Link(
      constructLocalAppData,
      name,
      info?.scriptsDir ?? null,
      link,
      ConstructUpdates.nodeConstructFileSystem,
    );
    if (!written.ok) {
      yield* logUpdaterWarning("could not record the T3 link", { instance: name, error: written.error });
      return false;
    }
    yield* logUpdaterInfo("recorded the T3 link", { instance: name, status: link.status });
    // Re-read the markers so the published instances carry the new marker at once.
    yield* refreshConstruct("t3-link", "local");
    return true;
  },
),

// Construct: a pairing link with the ADMINISTRATIVE scope set, for the Desktop app's
// automatic link of a VM (Get-ConstructT3PairingLink.ps1 asks for it when the flag exists).
const scopesFlag = Flag.string("scopes").pipe(
  Flag.withDescription("Scope set of the token: `standard` (default) or `administrative`."),
  Flag.optional,
);

if (url.value.pathname === "/manifest.webmanifest") {
  const constructManifestFs = yield* FileSystem.FileSystem;
  // @effect-diagnostics-next-line preferSchemaOverJson:off - preserve the upstream-owned manifest.
  const manifest = JSON.parse(
    yield* constructManifestFs.readFileString(path.join(staticRoot, "manifest.webmanifest")),
  );
  const instance = process.env.CONSTRUCT_INSTANCE_NAME?.trim() || constructPwaHostname();
  // @effect-diagnostics-next-line preferSchemaOverJson:off - serialize the upstream manifest with VM labels.
  return HttpServerResponse.text(JSON.stringify({
    ...manifest,
    name: `T3 Code (${instance})`,
    short_name: `T3 ${instance}`,
  }), {
    contentType: "application/manifest+json",
    headers: { "Cache-Control": "no-cache" },
  });
}
